-- FullCourt PostgreSQL schema and demo data
-- Generated from FullCourt_Database.sql for Supabase PostgreSQL.
-- Run in a new Supabase project using the SQL Editor.

BEGIN;
SET client_encoding = 'UTF8';
SET timezone = 'UTC';
CREATE TABLE IF NOT EXISTS announcements (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tournament_id integer DEFAULT NULL,
  title varchar(180) NOT NULL,
  message text NOT NULL,
  priority varchar(30) NOT NULL DEFAULT 'normal',
  published_at timestamp DEFAULT CURRENT_TIMESTAMP,
  expires_at timestamp DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS api_rate_limits (
  bucket_key char(64) NOT NULL,
  action_name varchar(50) NOT NULL,
  window_started_at timestamp NOT NULL,
  request_count integer NOT NULL DEFAULT 1,
  PRIMARY KEY (bucket_key,action_name)
);

CREATE TABLE IF NOT EXISTS audit_logs (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  user_id integer DEFAULT NULL,
  action varchar(100) NOT NULL,
  module varchar(50) NOT NULL,
  ip_address varchar(45) DEFAULT NULL,
  user_agent varchar(255) DEFAULT NULL,
  details text DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS award_categories (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tournament_id integer NOT NULL,
  name varchar(100) NOT NULL,
  metric_key varchar(50) DEFAULT NULL,
  is_public smallint NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  CONSTRAINT award_categories_uniq_award_category UNIQUE (tournament_id,name)
);

CREATE TABLE IF NOT EXISTS basketball_stat_events (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  event_uuid char(36) NOT NULL,
  match_id integer NOT NULL,
  team_id integer NOT NULL,
  team_player_id integer DEFAULT NULL,
  event_type text NOT NULL,
  period smallint NOT NULL DEFAULT 1,
  game_clock_seconds integer NOT NULL DEFAULT 600,
  metadata_json text DEFAULT NULL,
  is_void smallint NOT NULL DEFAULT 0,
  recorded_by integer NOT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT basketball_stat_events_event_uuid UNIQUE (event_uuid)
);

CREATE TABLE IF NOT EXISTS bracket_nodes (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  bracket_id integer NOT NULL,
  match_id integer DEFAULT NULL,
  round integer NOT NULL,
  position_in_round integer NOT NULL,
  parent_node_1_id integer DEFAULT NULL,
  parent_node_2_id integer DEFAULT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS brackets (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tournament_id integer NOT NULL,
  format text NOT NULL,
  total_rounds integer NOT NULL DEFAULT 1,
  total_teams integer NOT NULL DEFAULT 2,
  seeding_type text DEFAULT 'automatic',
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT brackets_tournament_id UNIQUE (tournament_id)
);

CREATE TABLE IF NOT EXISTS courts (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  venue_id integer NOT NULL,
  court_name varchar(50) NOT NULL,
  sport_id integer DEFAULT NULL,
  is_available smallint DEFAULT 1,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS divisions (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tournament_id integer NOT NULL,
  name varchar(100) NOT NULL,
  age_group varchar(50) DEFAULT NULL,
  gender_category text NOT NULL DEFAULT 'open',
  format text NOT NULL DEFAULT 'round_robin',
  min_age integer DEFAULT NULL,
  max_age integer DEFAULT NULL,
  max_roster_size integer NOT NULL DEFAULT 15,
  eligibility_requirements text DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT divisions_uniq_tournament_division UNIQUE (tournament_id,name)
);

CREATE TABLE IF NOT EXISTS eligibility_documents (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  team_player_id integer NOT NULL,
  document_type varchar(80) NOT NULL,
  file_path varchar(255) NOT NULL,
  mime_type varchar(100) NOT NULL,
  id_type varchar(60) DEFAULT NULL,
  id_number_last4 varchar(4) DEFAULT NULL,
  id_birth_date date DEFAULT NULL,
  selfie_path varchar(255) DEFAULT NULL,
  selfie_mime_type varchar(100) DEFAULT NULL,
  birthdate_match boolean DEFAULT NULL,
  consent_confirmed boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'pending',
  review_notes text DEFAULT NULL,
  reviewed_by integer DEFAULT NULL,
  reviewed_at timestamp DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS eligibility_logs (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  team_player_id integer NOT NULL,
  action_by integer NOT NULL,
  status text NOT NULL,
  remarks text DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS email_verifications (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  email varchar(100) NOT NULL,
  purpose text NOT NULL,
  code_hash varchar(255) NOT NULL,
  expires_at timestamp NOT NULL,
  used_at timestamp DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS event_categories (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  sport_id integer NOT NULL,
  name varchar(100) NOT NULL,
  gender text NOT NULL DEFAULT 'open',
  player_count integer NOT NULL DEFAULT 1,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT event_categories_uniq_event_category_sport_name UNIQUE (sport_id,name)
);

CREATE TABLE IF NOT EXISTS game_assignments (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  match_id integer NOT NULL,
  user_id integer NOT NULL,
  assignment_role text NOT NULL,
  status text NOT NULL DEFAULT 'pending',
  qr_token_hash char(64) DEFAULT NULL,
  qr_expires_at timestamp DEFAULT NULL,
  qr_used_at timestamp DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT game_assignments_uniq_game_assignment UNIQUE (match_id,user_id,assignment_role)
);

CREATE TABLE IF NOT EXISTS game_lineups (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  match_id integer NOT NULL,
  team_player_id integer NOT NULL,
  is_present smallint NOT NULL DEFAULT 1,
  is_starter smallint NOT NULL DEFAULT 0,
  confirmed_by integer DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT game_lineups_uniq_game_lineup_player UNIQUE (match_id,team_player_id)
);

CREATE TABLE IF NOT EXISTS match_scores (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  match_id integer NOT NULL,
  team1_score integer DEFAULT 0,
  team2_score integer DEFAULT 0,
  current_period varchar(50) DEFAULT 'Q1',
  timer_seconds integer DEFAULT 600,
  is_timer_running smallint DEFAULT 0,
  detailed_data_json text DEFAULT NULL,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT match_scores_match_id UNIQUE (match_id)
);

CREATE TABLE IF NOT EXISTS matches (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tournament_id integer NOT NULL,
  division_id integer DEFAULT NULL,
  round_number integer NOT NULL DEFAULT 1,
  match_number integer NOT NULL DEFAULT 1,
  stage_name varchar(50) DEFAULT 'Regular Match',
  team1_id integer DEFAULT NULL,
  team2_id integer DEFAULT NULL,
  winner_team_id integer DEFAULT NULL,
  court_id integer DEFAULT NULL,
  scheduled_start_time timestamp DEFAULT NULL,
  scheduled_end_time timestamp DEFAULT NULL,
  actual_start_time timestamp DEFAULT NULL,
  actual_end_time timestamp DEFAULT NULL,
  lineups_confirmed_at timestamp DEFAULT NULL,
  reminder_30_sent_at timestamp DEFAULT NULL,
  rest_time_mins integer DEFAULT 15,
  status text NOT NULL DEFAULT 'scheduled',
  schedule_status text NOT NULL DEFAULT 'draft',
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS news (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  sport_id integer DEFAULT NULL,
  title varchar(160) NOT NULL,
  slug varchar(190) NOT NULL,
  summary varchar(500) DEFAULT NULL,
  body text DEFAULT NULL,
  cover_url varchar(255) DEFAULT NULL,
  author_id integer DEFAULT NULL,
  is_published smallint NOT NULL DEFAULT 0,
  published_at timestamp DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT news_slug UNIQUE (slug)
);

CREATE TABLE IF NOT EXISTS notifications (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  user_id integer NOT NULL,
  notification_type varchar(60) NOT NULL,
  title varchar(180) NOT NULL,
  message text NOT NULL,
  action_url varchar(255) DEFAULT NULL,
  dedupe_key varchar(120) DEFAULT NULL,
  read_at timestamp DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT notifications_uniq_notification_dedupe UNIQUE (dedupe_key)
);

CREATE TABLE IF NOT EXISTS organization_members (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  organization_id integer NOT NULL,
  user_id integer NOT NULL,
  role text NOT NULL,
  status text NOT NULL DEFAULT 'invited',
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT organization_members_uniq_org_member_role UNIQUE (organization_id,user_id,role)
);

CREATE TABLE IF NOT EXISTS organizations (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  name varchar(150) NOT NULL,
  organization_type text NOT NULL,
  slug varchar(160) NOT NULL,
  logo_url varchar(255) DEFAULT NULL,
  primary_color char(7) NOT NULL DEFAULT '#F97316',
  secondary_color char(7) NOT NULL DEFAULT '#18181B',
  tagline varchar(200) DEFAULT NULL,
  status text NOT NULL DEFAULT 'pending',
  public_scores smallint NOT NULL DEFAULT 1,
  public_player_profiles smallint NOT NULL DEFAULT 0,
  application_notes text DEFAULT NULL,
  reviewed_by integer DEFAULT NULL,
  reviewed_at timestamp DEFAULT NULL,
  created_by integer NOT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT organizations_slug UNIQUE (slug)
);

CREATE TABLE IF NOT EXISTS payments (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  team_id integer NOT NULL,
  tournament_id integer NOT NULL,
  payment_method text NOT NULL DEFAULT 'gcash',
  reference_number varchar(100) NOT NULL,
  amount decimal(10,2) NOT NULL,
  receipt_photo_url varchar(255) DEFAULT NULL,
  status text NOT NULL DEFAULT 'pending',
  verified_by integer DEFAULT NULL,
  remarks text DEFAULT NULL,
  verified_at timestamp DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS payments_unique_reference ON payments (LOWER(reference_number));

CREATE TABLE IF NOT EXISTS player_awards (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  award_category_id integer NOT NULL,
  user_id integer NOT NULL,
  status text NOT NULL DEFAULT 'recommended',
  confirmed_by integer DEFAULT NULL,
  confirmed_at timestamp DEFAULT NULL,
  PRIMARY KEY (id),
  CONSTRAINT player_awards_uniq_player_award UNIQUE (award_category_id,user_id)
);

CREATE TABLE IF NOT EXISTS player_game_minutes (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  match_id integer NOT NULL,
  team_player_id integer NOT NULL,
  seconds_played integer NOT NULL DEFAULT 0,
  last_entered_elapsed_seconds integer DEFAULT NULL,
  is_on_court smallint NOT NULL DEFAULT 0,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT player_game_minutes_uniq_match_player_minutes UNIQUE (match_id,team_player_id)
);

CREATE TABLE IF NOT EXISTS player_profiles (
  user_id integer NOT NULL,
  first_name varchar(80) DEFAULT NULL,
  last_name varchar(80) DEFAULT NULL,
  birth_date date DEFAULT NULL,
  height_cm decimal(5,2) DEFAULT NULL,
  primary_position text DEFAULT NULL,
  guardian_name varchar(150) DEFAULT NULL,
  guardian_contact varchar(50) DEFAULT NULL,
  guardian_consented_at timestamp DEFAULT NULL,
  is_public smallint NOT NULL DEFAULT 0,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id)
);

CREATE TABLE IF NOT EXISTS qr_attendance (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  sync_uuid char(36) DEFAULT NULL,
  match_id integer NOT NULL,
  team_id integer NOT NULL,
  user_id integer DEFAULT NULL,
  qr_hash varchar(64) NOT NULL,
  attendance_type text NOT NULL DEFAULT 'player_checkin',
  scanned_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  scanned_by integer NOT NULL,
  status text NOT NULL DEFAULT 'success',
  PRIMARY KEY (id),
  CONSTRAINT qr_attendance_uq_qr_attendance_sync UNIQUE (sync_uuid)
);

CREATE TABLE IF NOT EXISTS refresh_tokens (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  user_id integer NOT NULL,
  family_id char(36) NOT NULL,
  token_hash char(64) NOT NULL,
  expires_at timestamp NOT NULL,
  used_at timestamp DEFAULT NULL,
  revoked_at timestamp DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT refresh_tokens_token_hash UNIQUE (token_hash)
);

CREATE TABLE IF NOT EXISTS reports_log (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tournament_id integer DEFAULT NULL,
  report_type varchar(80) NOT NULL,
  generated_by integer NOT NULL,
  filters_json text DEFAULT NULL,
  file_url varchar(255) DEFAULT NULL,
  format text NOT NULL DEFAULT 'pdf',
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS schedule_constraints (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tournament_id integer NOT NULL,
  max_games_per_team_per_day integer DEFAULT 2,
  min_rest_minutes_between_games integer DEFAULT 120,
  default_match_duration_minutes integer DEFAULT 40,
  default_break_minutes integer DEFAULT 15,
  PRIMARY KEY (id),
  CONSTRAINT schedule_constraints_uniq_constraint_tournament UNIQUE (tournament_id)
);

CREATE TABLE IF NOT EXISTS score_corrections (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  match_id integer NOT NULL,
  original_home_score integer NOT NULL,
  original_away_score integer NOT NULL,
  requested_home_score integer NOT NULL,
  requested_away_score integer NOT NULL,
  reason text NOT NULL,
  supporting_notes text DEFAULT NULL,
  status text NOT NULL DEFAULT 'pending',
  requested_by integer NOT NULL,
  reviewed_by integer DEFAULT NULL,
  reviewed_at timestamp DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS sports (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  name varchar(50) NOT NULL,
  category text NOT NULL DEFAULT 'team',
  min_players_per_team integer NOT NULL DEFAULT 5,
  max_players_per_team integer NOT NULL DEFAULT 15,
  default_match_duration_mins integer NOT NULL DEFAULT 40,
  rules_summary text DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT sports_name UNIQUE (name)
);

CREATE TABLE IF NOT EXISTS standings (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tournament_id integer NOT NULL,
  team_id integer NOT NULL,
  played integer DEFAULT 0,
  won integer DEFAULT 0,
  lost integer DEFAULT 0,
  drawn integer DEFAULT 0,
  points_scored integer DEFAULT 0,
  points_against integer DEFAULT 0,
  net_points integer DEFAULT 0,
  tournament_points integer DEFAULT 0,
  rank_position integer DEFAULT 0,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS team_players (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  team_id integer NOT NULL,
  user_id integer DEFAULT NULL,
  student_id_number varchar(50) NOT NULL,
  jersey_number integer DEFAULT NULL,
  position varchar(50) DEFAULT NULL,
  eligibility_status text NOT NULL DEFAULT 'pending',
  request_type text NOT NULL DEFAULT 'coach_invitation',
  category_id integer DEFAULT NULL,
  verified_by integer DEFAULT NULL,
  remarks text DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS teams (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tournament_id integer NOT NULL,
  division_id integer DEFAULT NULL,
  team_name varchar(100) NOT NULL,
  short_name varchar(20) DEFAULT NULL,
  logo_url varchar(255) DEFAULT NULL,
  primary_color char(7) DEFAULT '#F97316',
  secondary_color char(7) DEFAULT '#18181B',
  coach_user_id integer NOT NULL,
  manager_user_id integer DEFAULT NULL,
  seed integer DEFAULT NULL,
  qr_code_hash varchar(64) DEFAULT NULL,
  status text NOT NULL DEFAULT 'pending_payment',
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT teams_qr_code_hash UNIQUE (qr_code_hash)
);

CREATE TABLE IF NOT EXISTS tournaments (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  organization_id integer DEFAULT NULL,
  name varchar(150) NOT NULL,
  season varchar(50) DEFAULT NULL,
  sport_id integer NOT NULL,
  format text NOT NULL DEFAULT 'single_elimination',
  seeding_type text NOT NULL DEFAULT 'automatic',
  rules text DEFAULT NULL,
  description text DEFAULT NULL,
  start_date date NOT NULL,
  end_date date NOT NULL,
  registration_deadline date DEFAULT NULL,
  registration_fee decimal(10,2) NOT NULL DEFAULT 0.00,
  status text NOT NULL DEFAULT 'upcoming',
  is_published smallint NOT NULL DEFAULT 0,
  created_by integer NOT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS users (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  student_faculty_id varchar(50) DEFAULT NULL,
  full_name varchar(100) NOT NULL,
  email varchar(100) DEFAULT NULL,
  password_hash varchar(255) NOT NULL,
  role text NOT NULL DEFAULT 'player',
  department_course varchar(100) DEFAULT NULL,
  year_level varchar(30) DEFAULT NULL,
  phone_number varchar(20) DEFAULT NULL,
  avatar_url varchar(255) DEFAULT NULL,
  is_active smallint DEFAULT 1,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT users_email UNIQUE (email),
  CONSTRAINT users_student_faculty_id UNIQUE (student_faculty_id),
  CONSTRAINT users_uq_users_phone_number UNIQUE (phone_number)
);

CREATE TABLE IF NOT EXISTS venue_availability (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  venue_id integer NOT NULL,
  unavailable_date date NOT NULL,
  note varchar(255) DEFAULT NULL,
  PRIMARY KEY (id),
  CONSTRAINT venue_availability_uniq_venue_date UNIQUE (venue_id,unavailable_date)
);

CREATE TABLE IF NOT EXISTS venue_blackouts (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  court_id integer NOT NULL,
  starts_at timestamp NOT NULL,
  ends_at timestamp NOT NULL,
  reason varchar(255) DEFAULT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS venues (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  organization_id integer DEFAULT NULL,
  name varchar(100) NOT NULL,
  location varchar(150) NOT NULL,
  operating_hours_json text DEFAULT NULL,
  approval_status varchar(20) NOT NULL DEFAULT 'pending',
  submitted_by integer DEFAULT NULL,
  reviewed_by integer DEFAULT NULL,
  reviewed_at timestamp DEFAULT NULL,
  review_notes varchar(500) DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

