-- Legacy scorekeeper workflow retained for the live scoreboard API.
CREATE TABLE IF NOT EXISTS match_officials (
  id BIGSERIAL PRIMARY KEY,
  match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role VARCHAR(40) NOT NULL,
  assigned_by BIGINT REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (match_id,user_id,role)
);
CREATE TABLE IF NOT EXISTS match_rosters (
  id BIGSERIAL PRIMARY KEY,
  match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  team_id BIGINT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  jersey_number VARCHAR(12), position VARCHAR(20), is_active SMALLINT NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (match_id,user_id)
);
CREATE TABLE IF NOT EXISTS game_events (
  id BIGSERIAL PRIMARY KEY,
  match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  event_type VARCHAR(60) NOT NULL,
  team_id BIGINT REFERENCES teams(id) ON DELETE SET NULL,
  player_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
  clock_seconds INTEGER, period VARCHAR(20), detail_json JSONB,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS fouls (
  id BIGSERIAL PRIMARY KEY,
  match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  player_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  team_id BIGINT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  foul_type VARCHAR(40) NOT NULL,
  recorded_by BIGINT REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS timeouts (
  id BIGSERIAL PRIMARY KEY,
  match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  team_id BIGINT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  timeout_number INTEGER NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active',
  duration_seconds INTEGER NOT NULL DEFAULT 60,
  recorded_by BIGINT REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (match_id,team_id,timeout_number)
);
CREATE TABLE IF NOT EXISTS substitutions (
  id BIGSERIAL PRIMARY KEY,
  match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  team_id BIGINT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  player_in_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  player_out_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  period VARCHAR(20), clock_seconds INTEGER,
  recorded_by BIGINT REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS match_officials_user_idx ON match_officials(user_id,match_id);
CREATE INDEX IF NOT EXISTS game_events_match_idx ON game_events(match_id,created_at DESC);
CREATE INDEX IF NOT EXISTS fouls_match_idx ON fouls(match_id,team_id);
CREATE INDEX IF NOT EXISTS timeouts_match_idx ON timeouts(match_id,team_id);

-- Self-reported age when registering; not a birth date or eligibility proof.
ALTER TABLE users ADD COLUMN IF NOT EXISTS age_at_registration SMALLINT
    CHECK (age_at_registration BETWEEN 1 AND 120);
ALTER TABLE users ADD COLUMN IF NOT EXISTS birth_date DATE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS address TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS coach_team_name VARCHAR(150);
ALTER TABLE users ADD COLUMN IF NOT EXISTS coaching_experience_years SMALLINT CHECK (coaching_experience_years BETWEEN 0 AND 120);
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS address TEXT;
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS contact_designation VARCHAR(100);

COMMIT;
CREATE TABLE IF NOT EXISTS platform_settings (
  id SMALLINT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  maintenance_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  maintenance_message VARCHAR(240) NOT NULL DEFAULT 'FullCourt is being improved. Some features may be temporarily unavailable.',
  registration_enabled BOOLEAN NOT NULL DEFAULT TRUE,
  updated_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
INSERT INTO platform_settings (id) VALUES (1) ON CONFLICT (id) DO NOTHING;
ALTER TABLE platform_settings ENABLE ROW LEVEL SECURITY;
